function resolvePricing(outcome, cache, productId) {
  if (outcome.ok) {
    cache.set(productId, outcome.price);
    return { price: outcome.price, stale: false };
  }
  const lastKnown = cache.get(productId);
  if (lastKnown !== undefined) {
    return { price: lastKnown, stale: true };
  }
  throw new Error(`pricing unavailable for ${productId}: ${outcome.reason}`);
}

